output_text:
[
  {
    "id": "take_cart_at_entrance",
    "text": "Shoppers are obliged to take the waiting cart from the entrance cart bay before doing the trip.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_bay": "at(1,5)",
        "cart_waiting_at_bay": "cartAt(1,5)",
        "co_located_with_waiting_cart": {
          "and": [
            "at_entrance_cart_bay",
            "cart_waiting_at_bay"
          ]
        }
      },
      "events": {
        "picked_up_entrance_cart": {
          "pre": {
            "and": [
              "co_located_with_waiting_cart",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "picked_up_entrance_cart"
    }
  },
  {
    "id": "cart_required_for_items",
    "text": "Taking shelf items is prohibited unless the shopper is currently holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "has_shopping_cart": "hasCart"
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "has_shopping_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Carrying groceries by hand is prohibited; items should be transported in a cart instead.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "return_cart_after_shopping",
    "text": "After any item is collected into the cart, the shopper is obliged to return the cart at the counter before leaving.",
    "abstraction": {
      "state_properties": {
        "at_cart_return_counter": "at(0,1)",
        "cart_parked_at_counter": "cartAt(0,1)"
      },
      "events": {
        "collected_item_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "returned_cart_at_counter": {
          "pre": {
            "and": [
              "hasCart",
              "at_cart_return_counter",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_counter"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "collected_item_with_cart",
      "discharge": "returned_cart_at_counter"
    }
  },
  {
    "id": "cart_drop_only_at_counter",
    "text": "Leaving a cart anywhere other than the designated counter at cell (0,1) is prohibited.",
    "abstraction": {
      "state_properties": {
        "at_designated_cart_return": "at(0,1)"
      },
      "events": {
        "left_cart_outside_return": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "at_designated_cart_return"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "left_cart_outside_return"
    }
  },
  {
    "id": "exit_only_after_cart_return",
    "text": "Exiting the supermarket is prohibited unless the cart has already been parked at the return counter.",
    "abstraction": {
      "state_properties": {
        "cart_returned": "cartAt(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "cart_returned"
          }
        ]
      }
    }
  },
  {
    "id": "do_not_bypass_waiting_cart",
    "text": "When standing at the entrance cart bay with the cart still waiting there, moving away without taking the cart is prohibited.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_bay": "at(1,5)",
        "cart_still_waiting": "cartAt(1,5)",
        "cart_available_here": {
          "and": [
            "at_entrance_cart_bay",
            "cart_still_waiting"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_available_here",
          "MOVE"
        ]
      }
    }
  },
  {
    "id": "no_shopping_after_cart_return",
    "text": "Once the cart is parked at the counter, further shopping interactions are prohibited.",
    "abstraction": {
      "state_properties": {
        "cart_already_returned": "cartAt(0,1)"
      },
      "events": {
        "post_return_shopping_interaction": {
          "pre": {
            "and": [
              "cart_already_returned",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_shopping_interaction"
    }
  }
]
